struct Person {
    name: String,
    age: u32,
}

fn main() {
    let people = vec![
        Person { name: "Ada".into(), age: 36 },
        Person { name: "Alan".into(), age: 41 },
        Person { name: "Grace".into(), age: 29 },
    ];
    for p in &people {
        println!("{} {}", p.name, p.age);
    }
}

